CategoryTheory.Presheaf.homEquivAmalgamation.{v₁, v₂, u₁, u₂} {C : Type u₁} [Category.{v₁, u₁} C] {A : Type u₂}
  [Category.{v₂, u₂} A] {P : Cᵒᵖ ⥤ A} {X : C} {S : Sieve X} {E : Aᵒᵖ}
  {x : FamilyOfElements (P ⋙ coyoneda.obj E) S.arrows} (hx : x.SieveCompatible) :
